const hosts = $json.result || [];
const hostids = hosts.map(h => h.hostid);
const now = Math.floor(Date.now() / 1000);
const timeFrom7d = now - (86400 * 7);
const nowStr = new Date().toLocaleString('pt-BR', { timeZone: 'America/Sao_Paulo' });

return [{
  json: {
    hosts,
    time_from: timeFrom7d,
    time_till: now,
    generated_at: nowStr,
    cpu_items_body: JSON.stringify({
      jsonrpc: '2.0', method: 'item.get', id: 2,
      params: { output: ['itemid', 'hostid', 'key_', 'lastvalue'], hostids, search: { key_: 'system.cpu.util' }, monitored: true }
    }),
    mem_items_body: JSON.stringify({
      jsonrpc: '2.0', method: 'item.get', id: 3,
      params: { output: ['itemid', 'hostid', 'key_', 'lastvalue'], hostids, search: { key_: 'vm.memory' }, monitored: true }
    }),
    disk_items_body: JSON.stringify({
      jsonrpc: '2.0', method: 'item.get', id: 4,
      params: { output: ['itemid', 'hostid', 'key_', 'lastvalue'], hostids, search: { key_: 'pused' }, monitored: true }
    }),
    uptime_items_body: JSON.stringify({
      jsonrpc: '2.0', method: 'item.get', id: 5,
      params: { output: ['itemid', 'hostid', 'key_', 'lastvalue'], hostids, search: { key_: 'system.uptime' }, monitored: true }
    })
  }
}];

const prep = $('Preparar Item Queries').item.json;
const cpuItems     = $('Buscar Items CPU').item.json.result     || [];
const memItemsRaw  = $('Buscar Items Memória').item.json.result  || [];
const diskItemsRaw = $('Buscar Items Disco').item.json.result   || [];
const uptimeItems  = $json.result || [];

const cpuByHost = {};
for (const item of cpuItems) {
  if (!cpuByHost[item.hostid]) cpuByHost[item.hostid] = item;
  else if (item.key_ === 'system.cpu.util') cpuByHost[item.hostid] = item;
}

const memByHost = {};
for (const item of memItemsRaw) {
  const k = item.key_;
  if (k.includes('util')) memByHost[item.hostid] = item;
  else if (k.includes('pused') && !memByHost[item.hostid]) memByHost[item.hostid] = item;
}

const diskByHost = {};
for (const item of diskItemsRaw) {
  const k = item.key_;
  if (k.includes('vm.memory') || k.includes('memory')) continue;
  const lv = parseFloat(item.lastvalue);
  if (isNaN(lv) || lv < 0 || lv > 100) continue;
  if (!diskByHost[item.hostid]) diskByHost[item.hostid] = item;
  else if (k.includes('C:') || k.includes('c:') || k === 'vfs.fs.size[/,pused]') diskByHost[item.hostid] = item;
}

const uptimeByHost = {};
for (const item of uptimeItems) {
  if (!uptimeByHost[item.hostid]) uptimeByHost[item.hostid] = item;
}

const cpuItemids = Object.values(cpuByHost).map(i => i.itemid);
const memItemids = Object.values(memByHost).map(i => i.itemid);

return [{
  json: {
    hosts: prep.hosts,
    time_from: prep.time_from,
    time_till: prep.time_till,
    generated_at: prep.generated_at,
    cpuByHost, memByHost, diskByHost, uptimeByHost,
    cpu_trend_body: JSON.stringify({
      jsonrpc: '2.0', method: 'trend.get', id: 6,
      params: { output: ['itemid', 'clock', 'value_avg'], itemids: cpuItemids, time_from: prep.time_from, time_till: prep.time_till }
    }),
    mem_trend_body: JSON.stringify({
      jsonrpc: '2.0', method: 'trend.get', id: 7,
      params: { output: ['itemid', 'clock', 'value_avg'], itemids: memItemids, time_from: prep.time_from, time_till: prep.time_till }
    })
  }
}];

const prep      = $('Preparar Trend Queries').item.json;
const cpuTrends = $('Buscar Trends CPU').item.json.result || [];
const memTrends = $json.result || [];

const CPU_TH = 5, MEM_TH = 20, CPU_HIGH = 20, DAY = 86400;
const now = prep.time_till;

const cpuI2H = {}, memI2H = {};
for (const [hid, item] of Object.entries(prep.cpuByHost)) cpuI2H[item.itemid] = hid;
for (const [hid, item] of Object.entries(prep.memByHost)) memI2H[item.itemid] = hid;

const cpuH = {}, memH = {};
for (const t of cpuTrends) {
  const h = cpuI2H[t.itemid]; if (!h) continue;
  if (!cpuH[h]) cpuH[h] = [];
  cpuH[h].push({ c: parseInt(t.clock), v: parseFloat(t.value_avg) });
}
for (const t of memTrends) {
  const h = memI2H[t.itemid]; if (!h) continue;
  if (!memH[h]) memH[h] = [];
  memH[h].push({ c: parseInt(t.clock), v: parseFloat(t.value_avg) });
}

function avgArr(arr) { return arr.length ? arr.reduce((s, x) => s + x, 0) / arr.length : null; }

const report = [];
for (const host of prep.hosts) {
  const id = host.hostid;
  const cpuArr = (cpuH[id] || []).sort((a, b) => a.c - b.c);
  const memArr = (memH[id] || []).sort((a, b) => a.c - b.c);

  const cpu24 = avgArr(cpuArr.filter(t => t.c >= now - DAY).map(t => t.v));
  const mem24 = avgArr(memArr.filter(t => t.c >= now - DAY).map(t => t.v));
  const cpu7d = avgArr(cpuArr.map(t => t.v));
  const mem7d = avgArr(memArr.map(t => t.v));

  let cpu = cpu24 !== null ? Math.round(cpu24 * 10) / 10 : null;
  let mem = mem24 !== null ? Math.round(mem24 * 10) / 10 : null;
  if (cpu === null) { const lv = parseFloat(prep.cpuByHost[id]?.lastvalue); if (!isNaN(lv)) cpu = Math.round(lv * 10) / 10; }
  if (mem === null) { const lv = parseFloat(prep.memByHost[id]?.lastvalue); if (!isNaN(lv)) mem = Math.round(lv * 10) / 10; }

  let disk = null;
  const dlv = parseFloat(prep.diskByHost[id]?.lastvalue);
  if (!isNaN(dlv)) disk = Math.round(dlv * 10) / 10;

  let uptime = null;
  const ulv = parseFloat(prep.uptimeByHost[id]?.lastvalue);
  if (!isNaN(ulv)) uptime = Math.floor(ulv / DAY);

  const cpuF3 = avgArr(cpuArr.filter(t => t.c < prep.time_from + 3 * DAY).map(t => t.v));
  const cpuL3 = avgArr(cpuArr.filter(t => t.c >= now - 3 * DAY).map(t => t.v));
  let trendDir = 'estavel';
  if (cpuF3 !== null && cpuL3 !== null) {
    if (cpuL3 - cpuF3 > 2) trendDir = 'subindo';
    else if (cpuF3 - cpuL3 > 2) trendDir = 'caindo';
  }

  let idleDays = 0;
  for (let d = 0; d < 7; d++) {
    const ds = now - (d + 1) * DAY, de = now - d * DAY;
    const dayVals = cpuArr.filter(t => t.c >= ds && t.c < de).map(t => t.v);
    if (!dayVals.length) break;
    if (dayVals.reduce((s, x) => s + x, 0) / dayVals.length < CPU_TH) idleDays++;
    else break;
  }

  let lastHigh = 'N/D nos ultimos 7 dias';
  for (let i = cpuArr.length - 1; i >= 0; i--) {
    if (cpuArr[i].v > CPU_HIGH) {
      lastHigh = new Date(cpuArr[i].c * 1000).toLocaleString('pt-BR', { timeZone: 'America/Sao_Paulo' });
      break;
    }
  }

  const score = cpu !== null && mem !== null ? Math.round((cpu + mem) / 2 * 10) / 10 : null;
  const hasData = cpu !== null && mem !== null;
  const isGhost = hasData && cpu < CPU_TH && mem < MEM_TH;

  report.push({
    hostid: id,
    host: host.name, hostname: host.host,
    cpu, mem, disk, uptime, score,
    cpu7d: cpu7d !== null ? Math.round(cpu7d * 10) / 10 : null,
    mem7d: mem7d !== null ? Math.round(mem7d * 10) / 10 : null,
    trendDir, idleDays, lastHigh,
    hasData, isGhost
  });
}

report.sort((a, b) => (a.score ?? 999) - (b.score ?? 999));

// === Persistencia: comparativo semanal e dias consecutivos fantasma ===
const staticData = $getWorkflowStaticData('global');

const prevScores = staticData['ghost_prev_scores'] || {};
for (const h of report) {
  const prev = prevScores[h.hostname] !== undefined ? prevScores[h.hostname] : null;
  h.scoreDelta = (prev !== null && h.score !== null) ? parseFloat((h.score - prev).toFixed(1)) : null;
}
const newScores = {};
for (const h of report) { if (h.score !== null) newScores[h.hostname] = h.score; }
staticData['ghost_prev_scores'] = newScores;

const ghostDays = staticData['ghost_consecutive_days'] || {};
const DEACTIVATION_THRESHOLD = 7;
for (const h of report) {
  if (h.hasData) {
    ghostDays[h.hostname] = h.isGhost ? (ghostDays[h.hostname] || 0) + 1 : 0;
  }
  h.consecutiveGhostDays = ghostDays[h.hostname] || 0;
  h.candidateDeactivation = h.consecutiveGhostDays >= DEACTIVATION_THRESHOLD;
}
staticData['ghost_consecutive_days'] = ghostDays;

const ghosts = report.filter(r => r.isGhost);
const noData  = report.filter(r => !r.hasData);
const top10   = report.filter(r => r.hasData).slice(0, 10);
const candidates = report.filter(r => r.candidateDeactivation);

return [{ json: {
  report, ghosts, noData, top10, candidates,
  total: prep.hosts.length,
  CPU_THRESHOLD: CPU_TH, MEM_THRESHOLD: MEM_TH,
  generated_at: prep.generated_at
} }];

const { candidates } = $json;
if (!candidates || candidates.length === 0) return [];

return candidates.map(h => ({
  json: {
    host_tag_body: JSON.stringify({
      jsonrpc: '2.0',
      method: 'host.update',
      params: {
        hostid: h.hostid,
        tags: [{ tag: 'deactivation-candidate', value: h.consecutiveGhostDays + 'd' }]
      },
      id: 1
    }),
    hostname: h.hostname,
    consecutiveGhostDays: h.consecutiveGhostDays
  }
}));

const { ghosts, noData, top10, total, CPU_THRESHOLD, MEM_THRESHOLD, generated_at, candidates } = $json;

const pct = v => v !== null && v !== undefined ? parseFloat(v).toFixed(1) + '%' : 'N/D';
const fmtUp = d => d === null ? 'N/D' : d + (d === 1 ? ' dia' : ' dias');
const fmtDelta = d => { if (d === null) return ''; return d > 0 ? ' (+' + d + ' vs ant.)' : d < 0 ? ' (' + d + ' vs ant.)' : ''; };
const trendLabel = t => ({ subindo: 'Subindo', caindo: 'Caindo', estavel: 'Constante' })[t] || t;
const color = ghosts.length === 0 ? '00B050' : ghosts.length > 5 ? 'CC0000' : 'FFA500';

const hostFacts = top10.map(h => {
  const scoreStr = h.score !== null ? h.score.toFixed(1) + fmtDelta(h.scoreDelta) : 'N/D';
  const tag = h.isGhost ? (h.candidateDeactivation ? ' [OCIOSO — CANDIDATO]' : ' [OCIOSO]') : (h.candidateDeactivation ? ' [CANDIDATO]' : '');
  return {
    name: '- ' + h.host + tag,
    value: 'Score: ' + scoreStr + ' | CPU: ' + pct(h.cpu) + ' (7d: ' + pct(h.cpu7d) + ') | Mem: ' + pct(h.mem) + ' (7d: ' + pct(h.mem7d) + ') | Uptime: ' + fmtUp(h.uptime) + ' | Ocioso: ' + h.idleDays + 'd | ' + trendLabel(h.trendDir)
  };
});

const sections = [{
  activityTitle: 'Relatorio de Hosts Ociosos',
  activitySubtitle: generated_at + ' | CPU < ' + CPU_THRESHOLD + '%, Memoria < ' + MEM_THRESHOLD + '%',
  facts: hostFacts,
  markdown: true
}];

if (candidates && candidates.length > 0) {
  sections.push({
    activityTitle: 'Candidatos para Desativacao',
    facts: candidates.map(h => ({ name: '- ' + h.host, value: h.consecutiveGhostDays + ' dias consecutivos. Tag aplicada no Zabbix.' })),
    markdown: true
  });
}

if (noData.length > 0) {
  sections.push({
    activityTitle: 'Sem Dados de Metrica',
    facts: noData.map(h => ({ name: '- ' + h.host, value: 'Sem dados de CPU ou Memoria' })),
    markdown: true
  });
}

return [{ json: { teams_body: JSON.stringify({ '@type': 'MessageCard', '@context': 'http://schema.org/extensions', themeColor: color, summary: 'Hosts ociosos: ' + ghosts.length + ' de ' + total, sections }) } }];

const { ghosts, top10, candidates, total, generated_at } = $json;

const now = new Date();
if (now.getDay() !== 1) return [];

const tz = { timeZone: 'America/Sao_Paulo' };
const staticData = $getWorkflowStaticData('global');
const snapshots = staticData['ghost_weekly_snapshots'] || [];

const today = now.toLocaleDateString('pt-BR', tz);
const weekNum = Math.ceil((now - new Date(now.getFullYear(), 0, 1)) / (7 * 86400000));
const weekLabel = 'Semana ' + weekNum + '/' + now.getFullYear();

const currentGhostNames = new Set(ghosts.map(h => h.hostname));
const lastWeek = snapshots[0];
const lastGhostNames = new Set(lastWeek?.ghostHosts || []);

const newGhosts  = ghosts.filter(h => !lastGhostNames.has(h.hostname));
const recovered  = (lastWeek?.ghostHosts || []).filter(hn => !currentGhostNames.has(hn));
const chronic    = ghosts.filter(h => lastGhostNames.has(h.hostname));
const weekCounts = [ghosts.length, ...snapshots.map(s => s.ghostCount)].slice(0, 4);
const trend      = weekCounts.length >= 2 ? weekCounts[0] - weekCounts[1] : 0;

const newSnap = {
  date: today, weekLabel,
  ghostCount: ghosts.length,
  ghostHosts: ghosts.map(h => h.hostname),
  top10: top10.map(h => h.hostname),
  candidateHosts: candidates.map(h => h.hostname),
  totalMonitored: total
};
snapshots.unshift(newSnap);
if (snapshots.length > 4) snapshots.pop();
staticData['ghost_weekly_snapshots'] = snapshots;

return [{ json: { weekLabel, newGhosts, recovered, chronic, trend, weekCounts, top10, candidates, total, generated_at, snapshots: snapshots.slice(0, 4) } }];

const { weekLabel, newGhosts, recovered, chronic, trend, weekCounts, top10, candidates, total, generated_at, snapshots } = $json;

const pct = v => v !== null && v !== undefined ? parseFloat(v).toFixed(1) + '%' : 'N/D';
const trendArrow = trend > 0 ? '+' + trend + ' vs semana anterior' : trend < 0 ? String(trend) + ' vs semana anterior' : 'Igual a semana anterior';
const color = trend > 0 ? 'CC0000' : trend < 0 ? '00B050' : 'FFA500';
const historico = weekCounts.length >= 2 ? weekCounts.slice().reverse().map(String).join(' / ') + ' ociosos (ultimas ' + weekCounts.length + ' semanas)' : '';

const sections = [{
  activityTitle: 'Resumo Semanal — Hosts Ociosos',
  activitySubtitle: weekLabel + ' | ' + generated_at + (historico ? ' | ' + historico : ''),
  facts: [
    { name: 'Tendencia', value: trendArrow },
    { name: 'Ociosos',   value: String(weekCounts[0] || 0) + ' de ' + String(total) + ' monitorados' },
    { name: 'Novos',     value: String(newGhosts.length) },
    { name: 'Recuperados', value: String(recovered.length) },
    { name: 'Cronicos',  value: String(chronic.length) }
  ],
  markdown: true
}];

if (newGhosts.length > 0) {
  sections.push({
    activityTitle: 'Novos Ociosos Esta Semana',
    facts: newGhosts.map(h => ({ name: '- ' + h.host, value: 'Score: ' + (h.score !== null ? h.score.toFixed(1) : 'N/D') + ' | CPU: ' + pct(h.cpu) + ' | Mem: ' + pct(h.mem) })),
    markdown: true
  });
}

if (recovered.length > 0) {
  sections.push({
    activityTitle: 'Recuperados Esta Semana',
    facts: recovered.map(hn => ({ name: '- ' + hn, value: 'Voltou a ter atividade' })),
    markdown: true
  });
}

if (chronic.length > 0) {
  sections.push({
    activityTitle: 'Ociosos por 2+ Semanas',
    facts: chronic.map(h => ({ name: '- ' + h.host, value: 'Score: ' + (h.score !== null ? h.score.toFixed(1) : 'N/D') + ' | ' + (h.consecutiveGhostDays || 0) + ' dias consecutivos' })),
    markdown: true
  });
}

if (candidates && candidates.length > 0) {
  sections.push({
    activityTitle: 'Candidatos para Desativacao',
    facts: candidates.map(h => ({ name: '- ' + h.host, value: h.consecutiveGhostDays + ' dias consecutivos. Tag aplicada no Zabbix.' })),
    markdown: true
  });
}

return [{ json: { teams_body: JSON.stringify({ '@type': 'MessageCard', '@context': 'http://schema.org/extensions', themeColor: color, summary: 'Resumo semanal: ' + (weekCounts[0] || 0) + ' host(s) ocioso(s)', sections }) } }];
